body.script:
const canvas = document.getElementById('c');
const ctx    = canvas.getContext('2d');

/* ── Grid dimensions ───────────────────────────────────────────────────── */
const COLS   = 120;
const ROWS   = 60;
const FONT_W = 11;   // px per column
const FONT_H = 20;   // px per row  (monospace char height)

/* The canvas pixel dimensions exactly match the grid                       */
canvas.width  = COLS * FONT_W;   // 1320
canvas.height = ROWS * FONT_H;   // 1200

/* ── Galaxy parameters ─────────────────────────────────────────────────── */
const GRADIENT  = ' .\'`^",:;Il!i><~+_-?][}{1)(|\\/tfjrxnuvczXYUJCLQ0OZmwqpdbkhao*#MW&8%B@$';
const NUM_ARMS  = 3;
const STARS     = 800;
const TWIST     = 0.50;
const NOISE     = 0.16;
const GLOW_R    = 0.40;
const TWINKLE   = 0.28;
const SPEED     = 0.32;   // radians / second
const SIZE      = 0.82;   // fraction of half-grid to use

/*
 * Aspect-ratio correction:
 *   Each cell is FONT_W × FONT_H pixels, so to make a circle look round
 *   in character-space we must scale Y radii by FONT_W / FONT_H.
 *   (Characters are taller than wide, so the Y spread in *cells* must be
 *    smaller to appear circular on screen.)
 */
const AR = FONT_W / FONT_H;   // ~0.55

/* ── Colour palette (r,g,b) ────────────────────────────────────────────── */
const PALETTE = [
  [  0,  15,  70],
  [  0,  50, 150],
  [ 20, 110, 210],
  [ 80, 165, 255],
  [180, 215, 255],
  [255, 255, 255],
];

function lerp(a, b, t) { return a + (b - a) * t; }

function paletteColor(t) {
  t = Math.max(0, Math.min(1, t));
  const s  = t * (PALETTE.length - 1);
  const lo = Math.floor(s);
  const hi = Math.min(lo + 1, PALETTE.length - 1);
  const f  = s - lo;
  return [
    Math.round(lerp(PALETTE[lo][0], PALETTE[hi][0], f)),
    Math.round(lerp(PALETTE[lo][1], PALETTE[hi][1], f)),
    Math.round(lerp(PALETTE[lo][2], PALETTE[hi][2], f)),
  ];
}

/* ── Seeded RNG (stable star layout) ──────────────────────────────────── */
function mulberry32(seed) {
  return function () {
    seed |= 0; seed = seed + 0x6D2B79F5 | 0;
    let t = Math.imul(seed ^ seed >>> 15, 1 | seed);
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}
const rand = mulberry32(0xDEADBEEF);

/* ── Star field ────────────────────────────────────────────────────────── */
const stars = [];
for (let i = 0; i < STARS; i++) {
  const arm    = Math.floor(rand() * NUM_ARMS);
  const dist   = Math.pow(rand(), 0.55);
  const angle  = (arm / NUM_ARMS) * Math.PI * 2
               + dist * TWIST * Math.PI * 2
               + (rand() - 0.5) * NOISE * Math.PI * 2;
  stars.push({
    dist,
    angle,
    brightness:    Math.pow(1 - dist, 0.65),
    twinklePhase:  rand() * Math.PI * 2,
    twinkleRate:   0.7 + rand() * 2.6,
  });
}

/* ── Dense core ────────────────────────────────────────────────────────── */
const CORE = 140;
const core = [];
for (let i = 0; i < CORE; i++) {
  core.push({
    r:  Math.pow(rand(), 2.2) * 0.16,
    a:  rand() * Math.PI * 2,
    br: 0.65 + rand() * 0.35,
    tp: rand() * Math.PI * 2,
    tr: 1.2 + rand() * 3.2,
  });
}

/* ── Render loop ───────────────────────────────────────────────────────── */
let time = 0;
let last = 0;

function frame(now) {
  const dt = Math.min((now - last) / 1000, 0.1);
  last  = now;
  time += dt;

  ctx.fillStyle = '#000';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  /* Galaxy centre in column / row coordinates */
  const cx = COLS / 2;
  const cy = ROWS / 2;

  /* Radii in *column* and *row* units.
     rx is the full half-width; ry = rx * AR makes stars that are spread
     equally in pixels (a circle) even though rows are shorter than cols). */
  const rx = (COLS / 2) * SIZE;
  const ry = rx * AR;

  const angle0 = time * SPEED;

  /* Brightness + colour accumulator per grid cell */
  const grid  = new Float32Array(COLS * ROWS);
  const gridC = new Array(COLS * ROWS).fill(null);

  function splat(gx, gy, br, col) {
    const ix = Math.round(gx);
    const iy = Math.round(gy);
    if (ix < 0 || ix >= COLS || iy < 0 || iy >= ROWS) return;
    const idx = iy * COLS + ix;
    if (br > grid[idx]) { grid[idx] = br; gridC[idx] = col; }

    /* Glow falloff to neighbours */
    const gr = Math.ceil(GLOW_R * 3);
    for (let dy = -gr; dy <= gr; dy++) {
      for (let dx = -gr; dx <= gr; dx++) {
        if (!dx && !dy) continue;
        const nx = ix + dx, ny = iy + dy;
        if (nx < 0 || nx >= COLS || ny < 0 || ny >= ROWS) continue;
        const d2 = dx * dx + dy * dy;
        const fo = br * GLOW_R / (1 + d2 * 1.6);
        const ni = ny * COLS + nx;
        if (fo > grid[ni]) { grid[ni] = fo; gridC[ni] = col; }
      }
    }
  }

  /* Core stars */
  for (const s of core) {
    const a  = s.a + angle0 * 0.35;
    const gx = cx + Math.cos(a) * s.r * rx;
    const gy = cy + Math.sin(a) * s.r * ry;
    const tw = 1 + Math.sin(time * s.tr + s.tp) * TWINKLE * 0.5;
    splat(gx, gy, Math.min(s.br * tw, 1), paletteColor(0.82 + s.br * 0.18));
  }

  /* Arm stars */
  for (const s of stars) {
    const a  = s.angle + angle0;
    const gx = cx + Math.cos(a) * s.dist * rx;
    const gy = cy + Math.sin(a) * s.dist * ry;
    const tw = 1 + Math.sin(time * s.twinkleRate + s.twinklePhase) * TWINKLE;
    splat(gx, gy, Math.min(s.brightness * tw, 1),
          paletteColor(s.brightness * 0.72 + s.dist * 0.08));
  }

  /* Draw ASCII characters */
  ctx.textBaseline = 'top';
  ctx.font = `${FONT_H - 2}px 'Courier New', monospace`;

  for (let row = 0; row < ROWS; row++) {
    for (let col = 0; col < COLS; col++) {
      const idx = row * COLS + col;
      const br  = grid[idx];
      if (br < 0.012) continue;
      const ci  = Math.min(Math.floor(br * (GRADIENT.length - 1)), GRADIENT.length - 1);
      const [r, g, b] = gridC[idx] || [80, 130, 220];
      ctx.fillStyle = `rgba(${r},${g},${b},${Math.min(br * 1.5, 1).toFixed(3)})`;
      ctx.fillText(GRADIENT[ci], col * FONT_W, row * FONT_H);
    }
  }

  requestAnimationFrame(frame);
}

requestAnimationFrame(ts => { last = ts; frame(ts); });
